cd /home/experimenter/experiments/runs/2026-10-01_01-37-11_claim-office-example-mapping_external-kesseler-2026-09-30-cc_opus-5-5-no-thinking; cat > src/premium.ts <<'EOF'
export interface Item {
  type: string;
}

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function componentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

export function basePremium(items: Item[]): number {
  const mainItems = items.filter((item) => item.type in MAIN_ITEM_BASE_PREMIUMS);
  const componentCount = items.length - mainItems.length;
  const mainItemsPremium = mainItems.reduce((sum, item) => sum + MAIN_ITEM_BASE_PREMIUMS[item.type], 0);
  return mainItemsPremium + componentsBasePremium(componentCount);
}
EOF
