import { basePremium, Item } from './premium';

export type { Item };

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;
const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT = 0.15;

function itemSurchargeRate(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE : 0;
  const enchantment = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0;
  return curse + enchantment;
}

function quote(step: QuoteStep, yearsWithMHPCO: number, isFollowUp: boolean): QuoteResult {
  const policyBase = basePremium(step.items);
  const loyalty = yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT : 0;
  const followUp = isFollowUp ? FOLLOW_UP_DISCOUNT : 0;
  const itemSurcharges = step.items.reduce((sum, item) => sum + basePremium([item]) * itemSurchargeRate(item), 0);
  return { premium: policyBase + itemSurcharges + policyBase * (FIRST_INSURANCE_SURCHARGE - loyalty - followUp) + PROCESSING_FEE };
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step, index) => quote(step, scenario.customer.yearsWithMHPCO, index > 0)) };
}

