  const loyalty = history.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT : 0;
  const followUp = history.isFollowUp ? FOLLOW_UP_DISCOUNT : 0;
  return FIRST_INSURANCE_SURCHARGE - loyalty - followUp;
