import { Item } from './premium';

export interface Damage {
  itemType: string;
  amount: number;
}

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;

function reimbursement(item: Item, amount: number): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT : amount;
}

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
    this.remainingCap = insuranceSum * CAP_FACTOR;
  }

  claim(damages: Damage[]): { payout: number; remainingCap: number } {
    const undamagedItems = [...this.items];
    const payout = damages.reduce((sum, damage) => {
      const item = undamagedItems.splice(undamagedItems.findIndex((candidate) => candidate.type === damage.itemType), 1)[0];
      return sum + reimbursement(item, damage.amount) - DEDUCTIBLE;
    }, 0);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

