export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function componentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  items.forEach((item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1));
  return counts;
}

function typeGroupBasePremium(type: string, count: number): number {
  if (type in MAIN_ITEM_BASE_PREMIUMS) {
    return MAIN_ITEM_BASE_PREMIUMS[type] * count;
  }
  if (COMPONENT_TYPES.has(type)) {
    return componentsBasePremium(count);
  }
  throw new Error(`Unknown item type: ${type}`);
}

export function basePremium(items: Item[]): number {
  return [...countByType(items)].reduce((sum, [type, count]) => sum + typeGroupBasePremium(type, count), 0);
}

export interface CustomerHistory {
  yearsWithMHPCO: number;
  isFollowUp: boolean;
}

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;

function itemSurchargePercent(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const enchantment = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curse + enchantment;
}

function policyAdjustmentPercent(history: CustomerHistory): number {
  const loyalty = history.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
  const followUp = history.isFollowUp ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT - loyalty - followUp;
}

export function quotePremium(items: Item[], history: CustomerHistory): number {
  const policyBase = basePremium(items);
  const itemSurchargesInPercent = items.reduce((sum, item) => sum + basePremium([item]) * itemSurchargePercent(item), 0);
  const policyAdjustmentInPercent = policyBase * policyAdjustmentPercent(history);
  const premiumInPercent = (policyBase + PROCESSING_FEE) * PERCENT + itemSurchargesInPercent + policyAdjustmentInPercent;
  return Math.ceil(premiumInPercent / PERCENT);
}
import { Item } from './premium';

export interface Damage {
  itemType: string;
  amount: number;
}

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;

function reimbursement(item: Item, amount: number): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT : amount;
}

function damagePayout(item: Item, amount: number): number {
  if (amount < 0) {
    throw new Error(`Damage amount must not be negative: ${amount}`);
  }
  return Math.max(reimbursement(item, amount) - DEDUCTIBLE, 0);
}

function takeItem(items: Item[], itemType: string): Item {
  const index = items.findIndex((item) => item.type === itemType);
  if (index < 0) {
    throw new Error(`Damaged item is not covered by the policy: ${itemType}`);
  }
  return items.splice(index, 1)[0];
}

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
    this.remainingCap = insuranceSum * CAP_FACTOR;
  }

  claim(damages: Damage[]): { payout: number; remainingCap: number } {
    const undamagedItems = [...this.items];
    const desiredPayout = damages.reduce(
      (sum, damage) => sum + damagePayout(takeItem(undamagedItems, damage.itemType), damage.amount),
      0,
    );
    const payout = Math.min(Math.floor(desiredPayout), this.remainingCap);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

